import base64
import os
print("BOOT TRACER: Main.py loaded - V1", flush=True)
import sys
import threading
import time
import zipfile
import shutil
import logging
import traceback

# Kivy configuration belongs in writable private storage, not the APK code tree.
if 'ANDROID_PRIVATE' in os.environ:
    _private_files = os.environ['ANDROID_PRIVATE']
    if os.path.basename(_private_files) == 'app':
        _private_files = os.path.dirname(_private_files)
    os.environ['KIVY_HOME'] = os.path.join(_private_files, '.kivy')
    os.makedirs(os.environ['KIVY_HOME'], exist_ok=True)

from kivy.app import App
from kivy.uix.screenmanager import ScreenManager, Screen, FadeTransition
from kivy.uix.boxlayout import BoxLayout
from kivy.uix.label import Label
from kivy.uix.progressbar import ProgressBar
from kivy.uix.image import Image
from kivy.clock import Clock
from kivy.core.window import Window

# Native binaries must come from the APK recipe, never a mutable remote download.
def configure_native_library():
    if 'ANDROID_PRIVATE' not in os.environ:
        return None
    for entry in sys.path:
        for relative in ('llama_cpp/libllama.so', 'llama_cpp/lib/libllama.so'):
            candidate = os.path.join(entry, relative)
            if os.path.isfile(candidate):
                os.environ['LLAMA_CPP_LIB'] = candidate
                return candidate
    logging.error('Bundled libllama.so missing: rebuild the APK with llamacpp_android.')
    return None

configure_native_library()

# --- PLATFORM IMPORTS ---
from kivy.utils import platform

# ALLMA BRAIN BLOB (Build 163)
ZIP_DATA = ""

# --- EXECUTION LOGIC ---

class SetupScreen(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        layout = BoxLayout(orientation='vertical', padding=[50, 100, 50, 100], spacing=20)
        
        # Try to load logo if available
        if os.path.exists('logo.png'):
            try:
                img = Image(source='logo.png', size_hint=(1, 0.4), allow_stretch=True, keep_ratio=True)
                layout.add_widget(img)
            except:
                pass
                
        self.label = Label(text="Initializing ALLMA Systems...", font_size='20sp', halign='center', valign='middle')
        self.label.bind(size=self.label.setter('text_size'))
        
        self.progress = ProgressBar(max=100, size_hint_y=None, height=20)
        
        layout.add_widget(self.label)
        layout.add_widget(self.progress)
        self.add_widget(layout)

    def on_enter(self):
        Clock.schedule_once(lambda dt: threading.Thread(target=self.extract_and_run).start(), 0.5)

    def extract_and_run(self):
        try:
            self.update_status("Decrypting Neural Core...", 10)
            if not ZIP_DATA:
                raise ValueError("ZIP_DATA is empty!")
                
            data = base64.b64decode(ZIP_DATA)
            
            self.update_status("Allocating Memory Space...", 30)
            app = App.get_running_app()
            data_dir = getattr(app, 'user_data_dir', '.')
            
            # Debug override
            if os.path.exists('unpacked_brain'):
                extract_path = os.path.abspath('unpacked_brain')
            else:
                extract_path = os.path.join(data_dir, 'allma_brain_v163')
            
            # Clean old versions
            if os.path.exists(extract_path):
                try:
                    shutil.rmtree(extract_path)
                except:
                    pass
            
            os.makedirs(extract_path, exist_ok=True)
            
            self.update_status("Deploying Cognitive Modules...", 50)
            zip_path = os.path.join(extract_path, 'brain.zip')
            
            with open(zip_path, 'wb') as f:
                f.write(data)
                
            with zipfile.ZipFile(zip_path, 'r') as zf:
                zf.extractall(extract_path)
                
            self.update_status("Synapsing Neural Network...", 80)
            
            if extract_path not in sys.path:
                sys.path.insert(0, extract_path)
            
            # Verify module exists
            if not os.path.exists(os.path.join(extract_path, 'allma_model')):
                 raise ImportError(f"allma_model not found in {extract_path}")

            # Import the actual app module
            try:
                from allma_model.ui.app_entry import AllmaInternalApp
                self.update_status("Launching Core System...", 100)
                
                # Switch to the internal app
                Clock.schedule_once(lambda dt: self.switch_to_internal_app(AllmaInternalApp))
            except ImportError as e:
                self.show_error(f"Internal App Not Found: {e}")
            
        except Exception as e:
            err = traceback.format_exc()
            logging.error(err)
            print(err)
            err_msg = str(e)
            Clock.schedule_once(lambda dt: self.show_error(err_msg))

    def update_status(self, text, val):
        Clock.schedule_once(lambda dt: self._update_ui(text, val))

    def _update_ui(self, text, val):
        self.label.text = text
        self.progress.value = val

    def show_error(self, err):
        self.label.text = f"CRITICAL ERROR:\n{err}"
        self.label.color = (1, 0.3, 0.3, 1)

    def switch_to_internal_app(self, InternalAppClass):
        # Instantiate the internal app to get its build result
        try:
            current_app = App.get_running_app()
            app_instance = InternalAppClass()
            new_root = app_instance.build()
            
            # Get the current running app (The Installer)
            current_app.internal_app = app_instance
            
            # Clear current screen and set new root
            Window.remove_widget(current_app.root)
            Window.add_widget(new_root)
            current_app.root = new_root
            app_instance.root = new_root
            app_instance.on_start()
        except Exception as e:
           self.show_error(f"App Launch Failed: {e}")

class AllmaApp(App):
    def on_pause(self):
        internal = getattr(self, 'internal_app', None)
        return internal.on_pause() if internal else True

    def on_resume(self):
        internal = getattr(self, 'internal_app', None)
        if internal:
            internal.on_resume()

    def on_stop(self):
        internal = getattr(self, 'internal_app', None)
        if internal:
            internal.on_stop()

    def build(self):
        sm = ScreenManager(transition=FadeTransition())
        # Ensure SetupScreen is defined or imported. Assuming it is available in context or kv.
        # Actually SetupScreen wasn't visible in the snippets, assuming it's above or dynamically created.
        # Wait, I saw 'sm.add_widget(SetupScreen(name='setup'))' in the original file. 
        # I MUST PRESERVE SetupScreen usage if it exists.
        # Since I can't see SetupScreen def, I will assume it's there.
        # I will just insert on_start AFTER build.
        sm.add_widget(SetupScreen(name='setup'))
        return sm

    def on_start(self):
        print("ALLMA BOOTSTRAP: on_start", flush=True)
        if platform == 'android':
            try:
                from android.permissions import request_permissions, Permission
                print("ALLMA BOOTSTRAP: Requesting Permissions...", flush=True)
                # Aggiunti POST_NOTIFICATIONS e FOREGROUND_SERVICE per Android 13+
                request_permissions([
                    Permission.RECORD_AUDIO,
                    Permission.CAMERA,
                    Permission.WRITE_EXTERNAL_STORAGE,
                    Permission.READ_EXTERNAL_STORAGE,
                    # Fallback permissivo per versioni moderne (verrà ignorato senza crash su SDK vecchi)
                    'android.permission.POST_NOTIFICATIONS',
                    'android.permission.FOREGROUND_SERVICE'
                ])
                
                # Background inference needs coordinated ownership/IPC before enabling
                # a second Python process against the same model and memory files.
            except Exception as e:
                print(f"ALLMA BOOTSTRAP: Permission or Service Request Failed: {e}", flush=True)

if __name__ == '__main__':
    try:
        AllmaApp().run()
    except Exception as e:
        with open('crash.log', 'w') as f:
            f.write(traceback.format_exc())
        print(traceback.format_exc())
